    'button',
    'charCode',
    'clientX',
    'clientY',
    'code',
    'ctrlKey',
    'deltaMode',
    'deltaX',
    'deltaY',
    'deltaZ',
    'key',
    'keyCode',
    'metaKey',
    'pageX',
    'pageY',
    'pointerId',
    'pointerType',
    'scale',
    'shiftKey',
    'target',
    'type',
    'relatedTarget',
    'which'
