    'deltaX',
    'deltaY',
    'deltaZ',
    'altKey',
    'button',
    'charCode',
    'clientX',
    'clientY',
    'code',
    'ctrlKey',
    'key',
    'keyCode',
    'metaKey',
    'pageX',
    'pageY',
    'pointerId',
    'pointerType',
    'shiftKey',
    'type',
    'relatedTarget',
    'which'
