/**
 * Converts a linear sRGB color to the oklab color space.
 *
 * See RenderColor.linearToOklab for more information.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const linear_sRGB_to_oklabWGSL = (vec3) => {
    return new WGSLStringModule('linear_sRGB_to_oklab', wgsl `linear_sRGB_to_oklab( ${vec3} )`, wgsl `
  fn linear_sRGB_to_oklab( color: vec3f ) -> vec3f {
    let l = 0.4122214708 * color.r + 0.5363325363 * color.g + 0.0514459929 * color.b;
    let m = 0.2119034982 * color.r + 0.6806995451 * color.g + 0.1073969566 * color.b;
    let s = 0.0883024619 * color.r + 0.2817188376 * color.g + 0.6299787005 * color.b;
  
    let l_ = ${cbrtWGSL(wgsl `l`)};
    let m_ = ${cbrtWGSL(wgsl `m`)};
    let s_ = ${cbrtWGSL(wgsl `s`)};
  
    return vec3(
      0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
      1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
      0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_
    );
  }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Converts an oklab color to the linear sRGB color space.
 *
 * See RenderColor.oklabToLinear for more information.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const oklab_to_linear_sRGBWGSL = (vec3) => {
    return new WGSLStringModule('oklab_to_linear_sRGB', wgsl `oklab_to_linear_sRGB( ${vec3} )`, wgsl `
    fn oklab_to_linear_sRGB( color: vec3f ) -> vec3f {
      let l_ = color.x + 0.3963377774 * color.y + 0.2158037573 * color.z;
      let m_ = color.x - 0.1055613458 * color.y - 0.0638541728 * color.z;
      let s_ = color.x - 0.0894841775 * color.y - 1.2914855480 * color.z;
    
      let l = l_ * l_ * l_;
      let m = m_ * m_ * m_;
      let s = s_ * s_ * s_;
    
      return vec3(
        4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
        -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
        -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s,
      );
    }
`);
};

