alpenglow.register('MainScanModule', MainScanModule);

// Copyright 2023-2025, University of Colorado Boulder
/**
 * Loads data (usually from main memory) with multiple values per thread, but reduces them into a single value per
 * thread. Supports multiple orders of data (both in access order and storage order).
 *
 * grainSize controls how many items are loaded per thread.
 *
 * For each thread, it will essentially load the first value, and then combine that with subsequently loaded values.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const LOAD_REDUCED_DEFAULTS = {
    loadExpression: null,
    loadStatements: null,
    inputOrder: 'blocked',
    inputAccessOrder: 'striped',
    sequentialReduceStyle: 'factored',
    useSelectIfOptional: false,
    orderOverride: false,
    ...GLOBAL_INDEXABLE_DEFAULTS, // eslint-disable-line phet/no-object-spread-on-non-literals
    ...WORKGROUP_INDEXABLE_DEFAULTS, // eslint-disable-line phet/no-object-spread-on-non-literals
    ...LOCAL_INDEXABLE_DEFAULTS, // eslint-disable-line phet/no-object-spread-on-non-literals
    ...OPTIONAL_LENGTH_EXPRESSIONABLE_DEFAULTS // eslint-disable-line phet/no-object-spread-on-non-literals
};
const loadReducedWGSL = (providedOptions) => {
    const options = optionize3()({}, LOAD_REDUCED_DEFAULTS, providedOptions);
    const value = options.value;
    const binaryOp = options.binaryOp;
    const loadExpression = options.loadExpression;
    const loadStatements = options.loadStatements;
    const workgroupSize = options.workgroupSize;
    const grainSize = options.grainSize;
    const globalIndex = options.globalIndex;
    const workgroupIndex = options.workgroupIndex;
    const localIndex = options.localIndex;
    const lengthExpression = options.lengthExpression;
    const inputOrder = options.inputOrder;
    const inputAccessOrder = options.inputAccessOrder;
    const sequentialReduceStyle = options.sequentialReduceStyle;
    const useSelectIfOptional = options.useSelectIfOptional;
    const orderOverride = options.orderOverride;
    assert && assert(value);
    assert && assert(workgroupSize);
    assert && assert(grainSize);
    assert && assert(!lengthExpression || (inputOrder === 'blocked' || inputOrder === 'striped'), 'If range checks are enabled, inputOrder is required');
    assert && assert(inputAccessOrder === 'blocked' || inputAccessOrder === 'striped');
    assert && assert(inputOrder !== 'striped' || inputAccessOrder !== 'blocked', 'Do not use blocked order on striped data');
    assert && assert([loadExpression, loadStatements].filter(_.identity).length === 1, 'Must provide exactly one of loadExpression or loadStatements');
    assert && assert(orderOverride || binaryOp.isCommutative || inputOrder === inputAccessOrder, 'Unless you know what you are doing (orderOverride), cannot do an out-of-order reduce on non-commutative data');
    const outerDeclarations = [];
    const loadDeclarations = [];
    let loadIndexExpression = null;
    let rangeCheckIndexExpression = null;
    if (inputAccessOrder === 'blocked') {
        if (sequentialReduceStyle === 'factored') {
            outerDeclarations.push(wgsl `let base_blocked_index = ${u32S(grainSize)} * ${globalIndex};`);
            loadDeclarations.push(i => wgsl `let blocked_index = base_blocked_index + ${u32S(i)};`); // TODO: simplify i=0?
            loadIndexExpression = () => wgsl `blocked_index`;
            if (lengthExpression !== null) {
                // NOTE: only have to do the 'blocked' case, since for striped data we're not supporting blocked access order
                rangeCheckIndexExpression = loadIndexExpression;
            }
        }
        else {
            loadIndexExpression = i => wgsl `${u32S(grainSize)} * ${globalIndex} + ${u32S(i)}`; // TODO: simplify i=0?
            if (lengthExpression !== null) {
                // NOTE: only have to do the 'blocked' case, since for striped data we're not supporting blocked access order
                rangeCheckIndexExpression = loadIndexExpression;
            }
        }
    }
    else if (inputAccessOrder === 'striped') {
        if (sequentialReduceStyle === 'factored') {
            if (inputOrder === 'striped' && lengthExpression) {
                outerDeclarations.push(wgsl `let base_workgroup = ${workgroupIndex} * ${u32S(workgroupSize * grainSize)};`);
                outerDeclarations.push(wgsl `let base_striped_index = base_workgroup + ${localIndex};`);
                outerDeclarations.push(wgsl `let base_blocked_index = base_workgroup + ${localIndex} * ${u32S(grainSize)};`);
            }
            else {
                outerDeclarations.push(wgsl `let base_striped_index = ${workgroupIndex} * ${u32S(workgroupSize * grainSize)} + ${localIndex};`);
            }
            loadDeclarations.push(i => wgsl `let striped_index = base_striped_index + ${u32S(i * workgroupSize)};`);
            loadIndexExpression = () => wgsl `striped_index`;
            if (lengthExpression !== null) {
                if (inputOrder === 'striped') {
                    rangeCheckIndexExpression = i => wgsl `base_blocked_index + ${u32S(i)}`; // TODO: simplify i=0?
                }
                else if (inputOrder === 'blocked') {
                    rangeCheckIndexExpression = loadIndexExpression;
                }
                else {
                    throw new Error(`Unrecognized inputOrder: ${inputOrder}`);
                }
            }
        }
        else {
            loadIndexExpression = i => wgsl `${workgroupIndex} * ${u32S(workgroupSize * grainSize)} + ${localIndex} + ${u32S(i * workgroupSize)}`;
            if (lengthExpression !== null) {
                if (inputOrder === 'striped') {
                    rangeCheckIndexExpression = i => wgsl `${workgroupIndex} * ${u32S(workgroupSize * grainSize)} + ${localIndex} * ${u32S(grainSize)} + ${u32S(i)}`; // TODO: simplify i=0?
                }
                else if (inputOrder === 'blocked') {
                    rangeCheckIndexExpression = loadIndexExpression;
                }
                else {
                    throw new Error(`Unrecognized inputOrder: ${inputOrder}`);
                }
            }
        }
    }
    else {
        throw new Error(`Unrecognized inputAccessOrder: ${inputAccessOrder}`);
    }
    assert && assert(!rangeCheckIndexExpression === (lengthExpression === null), 'rangeCheckIndexExpression must be created iff length is provided');
    // TODO: factor out length expression conditionally, since sometimes it might duplicate buffer loads(!)
    const loadWithRangeCheckExpression = (i) => rangeCheckIndexExpression
        ? wgsl `select( ${binaryOp.identityWGSL}, ${loadExpression(loadIndexExpression(i))}, ${rangeCheckIndexExpression(i)} < ${lengthExpression} )`
        : loadExpression(loadIndexExpression(i));
    const ifRangeCheck = (i, trueStatements, falseStatements = null) => {
        return conditionalIfWGSL(rangeCheckIndexExpression ? wgsl `${rangeCheckIndexExpression(i)} < ${lengthExpression}` : null, trueStatements, falseStatements);
    };
    const indexedLoadStatements = (varName, i, declaration) => loadExpression ? wgsl `
    ${declaration ? wgsl `${declaration} ` : wgsl ``}${varName} = ${loadExpression(loadIndexExpression(i))};
  ` : wgsl `
    ${declaration ? wgsl `
      var ${varName}: ${binaryOp.type.valueType};
    ` : wgsl ``}
    ${loadStatements(varName, loadIndexExpression(i))}
  `;
    const loadWithRangeCheckStatements = (varName, i) => ifRangeCheck(i, wgsl `
    ${indexedLoadStatements(varName, i)}
  `, wgsl `
    ${varName} = ${binaryOp.identityWGSL};
  `);
    const getNestedExpression = (i) => {
        return i === 0 ? loadWithRangeCheckExpression(0) : binaryOp.combineExpression(getNestedExpression(i - 1), loadWithRangeCheckExpression(i));
    };
    const combineToValue = (varName, a, b) => {
        return binaryExpressionStatementWGSL(varName, binaryOp.combineExpression || null, binaryOp.combineStatements || null, a, b);
    };
    // TODO: more unique names to prevent namespace collision!
    return sequentialReduceStyle === 'nested' ? wgsl `
    var ${value} = ${getNestedExpression(grainSize - 1)};
  ` : wgsl `
    ${commentWGSL('begin load_reduced')}
    var ${value}: ${binaryOp.type.valueType};
    {
      ${wgslJoin('\n', outerDeclarations)}
      {
        ${wgslJoin('\n', loadDeclarations.map(declaration => declaration(0)))}
        ${(loadExpression && useSelectIfOptional) ? wgsl `
          ${value} = ${loadWithRangeCheckExpression(0)};
        ` : wgsl `
          ${loadWithRangeCheckStatements(value, 0)}
        `}
      }
      ${unrollWGSL(1, grainSize, i => wgsl `
        {
          ${wgslJoin('\n', loadDeclarations.map(declaration => declaration(i)))}
          ${(loadExpression && useSelectIfOptional) ? wgsl `
            ${combineToValue(value, value, loadWithRangeCheckExpression(i))}
          ` : wgsl `
            ${ifRangeCheck(i, wgsl `
              ${indexedLoadStatements(wgsl `next_value`, i, wgsl `let`)}
              ${combineToValue(value, value, wgsl `next_value`)}
            `)}
          `}
        }
      `)}
    }
    ${commentWGSL('end load_reduced')}
  `;
};
alpenglow.register('loadReducedWGSL', loadReducedWGSL);

// Copyright 2023-2025, University of Colorado Boulder
/**
 * A template that performs a reduce operation on a single workgroup. The value will be valid at local_id.x === 0.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const REDUCE_DEFAULTS = {
    mapScratchIndex: _.identity,
    convergent: false,
    scratchPreloaded: false,
    valuePreloaded: true,
    ...LOCAL_INDEXABLE_DEFAULTS // eslint-disable-line phet/no-object-spread-on-non-literals
};
const reduceWGSL = (providedOptions) => {
    const options = optionize3()({}, REDUCE_DEFAULTS, providedOptions);
    const value = options.value;
    const scratch = options.scratch;
    const workgroupSize = options.workgroupSize;
    const binaryOp = options.binaryOp;
    const localIndex = options.localIndex;
    const mapScratchIndex = options.mapScratchIndex;
    const convergent = options.convergent;
    const scratchPreloaded = options.scratchPreloaded;
    const valuePreloaded = options.valuePreloaded;
    assert && assert(!convergent || Number.isInteger(Math.log2(workgroupSize)));
    assert && assert(scratchPreloaded || valuePreloaded);
    const start = convergent ? Math.log2(workgroupSize) : 0;
    const end = convergent ? 0 : Math.log2(workgroupSize);
    const condition = (i) => convergent
        ? wgsl `${localIndex} < ${u32S(1 << (i - 1))}`
        : wgsl `${localIndex} % ${u32S(1 << (i + 1))} == 0u`;
    const accessIndex = (i) => convergent
        ? wgsl `${localIndex} + ${u32S(1 << (i - 1))}`
        : wgsl `${localIndex} + ${u32S(1 << i)}`;
    const combineToValue = (varName, a, b) => {
        return binaryExpressionStatementWGSL(varName, binaryOp.combineExpression || null, binaryOp.combineStatements || null, a, b);
    };
    return wgsl `
    ${commentWGSL(`begin reduce convergent:${convergent}`)}
    ${!scratchPreloaded ? wgsl `
      ${scratch}[ ${mapScratchIndex(localIndex)} ] = ${value};
    ` : wgsl ``}
    ${!valuePreloaded ? wgsl `
      ${value} = ${scratch}[ ${mapScratchIndex(localIndex)} ];
    ` : wgsl ``}
    
    ${logValueWGSL({
        name: `before reduce convergent:${convergent}`,
        value: 'value',
        type: binaryOp.type
    })}
    
    ${unrollWGSL(start, end, (i, isFirst, isLast) => wgsl `
      // We don't need the first workgroupBarrier() if scratchPreloaded is true
      ${!scratchPreloaded || !isFirst ? wgsl `
        workgroupBarrier();
      ` : wgsl ``}

      // TODO: check performance differences with a select/combine?
      if ( ${condition(i)} ) {
        ${combineToValue(value, value, wgsl `${scratch}[ ${mapScratchIndex(accessIndex(i))} ]`)}

        ${!isLast ? wgsl `
          ${scratch}[ ${mapScratchIndex(localIndex)} ] = ${value};
        ` : wgsl ``}
      }
    `)}
    ${commentWGSL('end reduce')}
  `;
};
alpenglow.register('reduceWGSL', reduceWGSL);

// Copyright 2023-2025, University of Colorado Boulder
/**
 * Returns the bit-reversed version of the given value, such that it is sufficient for the convergent-indexed reduce.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const getConvergentIndexWGSL = (options) => {
    const i = options.i;
    const size = options.size;
    return wgsl `( reverseBits( ${i} ) >> ${u32S(32 - Math.log2(size))} )`;
};
alpenglow.register('getConvergentIndexWGSL', getConvergentIndexWGSL);
const toConvergentIndexWGSL = getConvergentIndexWGSL;
alpenglow.register('toConvergentIndexWGSL', toConvergentIndexWGSL);
const fromConvergentIndexWGSL = getConvergentIndexWGSL;
alpenglow.register('fromConvergentIndexWGSL', fromConvergentIndexWGSL);

// Copyright 2023-2025, University of Colorado Boulder
/**
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const MAIN_REDUCE_DEFAULTS = {
    stripeOutput: false,
    convergentRemap: false,
    loadReducedOptions: {},
    reduceOptions: {}
};
const mainReduceWGSL = (providedOptions) => {
    const options = optionize3()({}, MAIN_REDUCE_DEFAULTS, providedOptions);
    const workgroupSize = options.workgroupSize;
    const grainSize = options.grainSize;
    const binaryOp = options.binaryOp;
    const stripeOutput = options.stripeOutput;
    const convergentRemap = options.convergentRemap;
    return new WGSLMainModule([
        new WGSLSlot('input', options.input, BufferBindingType.READ_ONLY_STORAGE),
        new WGSLSlot('output', options.output, BufferBindingType.STORAGE)
    ], wgsl `
    var<workgroup> scratch: array<${binaryOp.type.valueType}, ${decimalS(workgroupSize)}>;
    
    @compute @workgroup_size(${decimalS(workgroupSize)})
    fn main(
      @builtin(global_invocation_id) global_id: vec3u,
      @builtin(local_invocation_id) local_id: vec3u,
      @builtin(workgroup_id) workgroup_id: vec3u
    ) {
      ${logStringWGSL(`mainReduceWGSL start ${binaryOp.name}`)}
    
      ${loadReducedWGSL(combineOptions({
        value: wgsl `value`,
        binaryOp: binaryOp,
        loadExpression: i => wgsl `input[ ${i} ]`,
        workgroupSize: workgroupSize,
        grainSize: grainSize
    }, options.loadReducedOptions))}
    
      ${convergentRemap ? wgsl `
        scratch[ ${toConvergentIndexWGSL({ i: wgsl `local_id.x`, size: workgroupSize })} ] = value;
    
        workgroupBarrier();
      ` : wgsl ``}
    
      ${reduceWGSL(combineOptions({
        value: wgsl `value`,
        binaryOp: binaryOp,
        scratch: wgsl `scratch`,
        workgroupSize: workgroupSize,
        scratchPreloaded: convergentRemap, // if we convergently reloaded, we don't need to update the scratch
        valuePreloaded: !convergentRemap // if we convergently reloaded, we'll need to load the value from scratch
    }, options.reduceOptions))}
    
      if ( local_id.x == 0u ) {
        output[ ${stripeOutput ? toStripedIndexWGSL({
        i: wgsl `workgroup_id.x`,
        workgroupSize: workgroupSize,
        grainSize: grainSize
    }) : wgsl `workgroup_id.x`} ] = value;
      }
    }
  `);
};
alpenglow.register('mainReduceWGSL', mainReduceWGSL);

