/**
 * Multiplies two u32s together, returning a u64.
 *
 * TODO: karatsuba multiplication
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const mul_u32_u32_to_u64WGSL = (a, b) => {
    // ( a_low + a_high * 2^16 ) * ( b_low + b_high * 2^16 )
    // ( a_low * b_low ) + ( a_low * b_high + a_high * b_low ) * 2^16 + ( a_high * b_high ) * 2^32
    return new WGSLStringModule('mul_u32_u32_to_u64', wgsl `mul_u32_u32_to_u64( ${a}, ${b} )`, wgsl `
    fn mul_u32_u32_to_u64( a: u32, b: u32 ) -> ${u64WGSL} {
      let a_low = a & 0xffffu;
      let a_high = a >> 16u;
      let b_low = b & 0xffffu;
      let b_high = b >> 16u;
      let c_low = a_low * b_low;
      let c_mid = a_low * b_high + a_high * b_low;
      let c_high = a_high * b_high;
      let low = ${add_u32_u32_to_u64WGSL(wgsl `c_low`, wgsl `c_mid << 16u`)};
      let high = vec2( 0u, ( c_mid >> 16u ) + c_high );
      return low + high;
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Multiplies two u64s together, returning a u64 (the low 64 bits of the result)
 *
 * TODO: karatsuba?
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const mul_u64_u64WGSL = (a, b) => {
    // ( a_low + a_high * 2^32 ) * ( b_low + b_high * 2^32 ) mod 2^64
    // = a_low * b_low + a_low * b_high * 2^32 + a_high * b_low * 2^32 + a_high * b_high * 2^64 mod 2^64
    // = a_low * b_low + ( a_low * b_high + a_high * b_low ) * 2^32 mod 2^64
    return new WGSLStringModule('mul_u64_u64', wgsl `mul_u64_u64( ${a}, ${b} )`, wgsl `
    fn mul_u64_u64( a: ${u64WGSL}, b: ${u64WGSL} ) -> ${u64WGSL} {
      let low = ${mul_u32_u32_to_u64WGSL(wgsl `a.x`, wgsl `b.x`)};
      let mid0 = vec2( 0u, ${mul_u32_u32_to_u64WGSL(wgsl `a.x`, wgsl `b.y`)}.x );
      let mid1 = vec2( 0u, ${mul_u32_u32_to_u64WGSL(wgsl `a.y`, wgsl `b.x`)}.x );
      return ${add_u64_u64WGSL(add_u64_u64WGSL(wgsl `low`, wgsl `mid0`), wgsl `mid1`)};
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Multiplies two i64s together, returning an i64 (the low 64 bits of the result)
 *
 * TODO: karatsuba?
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const mul_i64_i64WGSL = (a, b) => {
    return new WGSLStringModule('mul_i64_i64', wgsl `mul_i64_i64( ${a}, ${b} )`, wgsl `
    fn mul_i64_i64( a: ${i64WGSL}, b: ${i64WGSL} ) -> ${i64WGSL} {
      var result = ${mul_u64_u64WGSL(abs_i64WGSL(wgsl `a`), abs_i64WGSL(wgsl `b`))};
      result.y &= 0x7fffffffu; // remove the sign bit
      if ( ${is_negative_i64WGSL(wgsl `a`)} != ${is_negative_i64WGSL(wgsl `b`)} ) {
        return ${negate_i64WGSL(wgsl `result`)};
      }
      else {
        return result;
      }
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Checks whether two rational numbers are equal (by using cross-multiplication).
 *
 * IMPORTANT NOTE: this only works if we have the bits to spare (where numerator * denominator does NOT overflow)
 * to avoid reduction. Reduction would also work.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const equals_cross_mul_q128WGSL = (a, b) => {
    return new WGSLStringModule('equals_cross_mul_q128', wgsl `equals_cross_mul_q128( ${a}, ${b} )`, wgsl `
    fn equals_cross_mul_q128( a: ${q128WGSL}, b: ${q128WGSL} ) -> bool {
      return ${is_zero_u64WGSL(subtract_i64_i64WGSL(mul_i64_i64WGSL(wgsl `a.xy`, wgsl `b.zw`), mul_i64_i64WGSL(wgsl `a.zw`, wgsl `b.xy`)))};
    }
  `);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Returns the position of the first trailing bit (least significant bit) in a u64.
 *
 * NOTE: ASSUMES NONZERO
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const first_trailing_bit_u64WGSL = (u64) => {
    return new WGSLStringModule('first_trailing_bit_u64', wgsl `first_trailing_bit_u64( ${u64} )`, wgsl `
    fn first_trailing_bit_u64( a: ${u64WGSL} ) -> u32 {
      if ( a.x != 0u ) {
        return firstTrailingBit( a.x );
      }
      else {
        return firstTrailingBit( a.y ) + 32u;
      }
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Binary GCD of two u64s.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const gcd_u64_u64WGSL = (a, b) => {
    return new WGSLStringModule('gcd_u64_u64', wgsl `gcd_u64_u64( ${a}, ${b} )`, wgsl `
    fn gcd_u64_u64( a: ${u64WGSL}, b: ${u64WGSL} ) -> ${u64WGSL} {
      if ( ${is_zero_u64WGSL(wgsl `a`)} ) {
        return b;
      }
      else if ( ${is_zero_u64WGSL(wgsl `b`)} ) {
        return a;
      }
    
      let gcd_two = ${first_trailing_bit_u64WGSL(wgsl `a | b`)};
    
      var u = ${right_shift_u64WGSL(wgsl `a`, wgsl `gcd_two`)};
      var v = ${right_shift_u64WGSL(wgsl `b`, wgsl `gcd_two`)};
    
      while ( u.x != v.x || u.y != v.y ) {
        if ( ${cmp_u64_u64WGSL(wgsl `u`, wgsl `v`)} == -1i ) {
          let t = u;
          u = v;
          v = t;
        }
    
        u = ${subtract_i64_i64WGSL(wgsl `u`, wgsl `v`)};
        u = ${right_shift_u64WGSL(wgsl `u`, first_trailing_bit_u64WGSL(wgsl `u`))};
      }
    
      return ${left_shift_u64WGSL(wgsl `u`, wgsl `gcd_two`)};
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Converts an i32 to an i64.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const i32_to_i64WGSL = (i64) => {
    return new WGSLStringModule('i32_to_i64', wgsl `i32_to_i64( ${i64} )`, wgsl `
    fn i32_to_i64( x: i32 ) -> ${i64WGSL} {
      return vec2<u32>( u32( x ), select( 0u, 0xffffffffu, x < 0i ) );
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Converts i64 numerator and denominator to a rational q128.
 *
 * Basically, we just ensure the denominator is positive (negating both if it is negative).
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const i64_to_q128WGSL = (numerator, denominator) => {
    return new WGSLStringModule('i64_to_q128', wgsl `i64_to_q128( ${numerator}, ${denominator} )`, wgsl `
    fn i64_to_q128( numerator: ${i64WGSL}, denominator: ${i64WGSL} ) -> ${q128WGSL} {
      if ( ${is_negative_i64WGSL(wgsl `denominator`)} ) {
        return vec4( ${negate_i64WGSL(wgsl `numerator`)}, ${negate_i64WGSL(wgsl `denominator`)} );
      }
      else {
        return vec4( numerator, denominator );
      }
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Checks whether a q128 (rational) is zero
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const is_zero_q128WGSL = (q128) => {
    return new WGSLStringModule('is_zero_q128', wgsl `is_zero_q128( ${q128} )`, wgsl `
    fn is_zero_q128( a: ${q128WGSL} ) -> bool {
      return a.x == 0u && a.y == 0u;
    }
  `);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Returns a range query on the rational (q128) value:
 *
 * 2i: totally internal (0<q<1)
 * 1i: on an endpoint (q=0 or q=1)
 * 0i: totally external (q<0 or q>1)
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const ratio_test_q128WGSL = (q128) => {
    return new WGSLStringModule('ratio_test_q128', wgsl `ratio_test_q128( ${q128} )`, wgsl `
    fn ratio_test_q128( q: ${q128WGSL} ) -> i32 {
      return ${cmp_i64_i64WGSL(wgsl `q.xy`, ZERO_u64WGSL)} + ${cmp_i64_i64WGSL(wgsl `q.zw`, wgsl `q.xy`)};
    }
  `);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Reduces a q128 (rational) to its simplest form.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const reduce_q128WGSL = (q128) => {
    return new WGSLStringModule('reduce_q128', wgsl `reduce_q128( ${q128} )`, wgsl `
    fn reduce_q128( a: ${q128WGSL} ) -> ${q128WGSL} {
      let numerator = a.xy;
      let denominator = a.zw;
      if ( numerator.x == 0u && numerator.y == 0u ) {
        return vec4( 0u, 0u, 1u, 0u ); // 0/1
      }
      else if ( denominator.x == 1 && denominator.y == 0u ) {
        return a; // we're already reduced, x/1
      }
      let abs_numerator = ${abs_i64WGSL(wgsl `numerator`)};
      let gcd = ${gcd_u64_u64WGSL(wgsl `abs_numerator`, wgsl `denominator`)};
      if ( gcd.x == 1u && gcd.y == 0u ) {
        return a;
      }
      else {
        let reduced_numerator = ${div_u64_u64WGSL(wgsl `abs_numerator`, wgsl `gcd`)}.xy;
        let reduced_denominator = ${div_u64_u64WGSL(wgsl `denominator`, wgsl `gcd`)}.xy;
        if ( ${is_negative_i64WGSL(wgsl `numerator`)} ) {
          return vec4( ${negate_i64WGSL(wgsl `reduced_numerator`)}, reduced_denominator );
        }
        else {
          return vec4( reduced_numerator, reduced_denominator );
        }
      }
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Converts an i64 to a rational q128 (whole number).
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const whole_i64_to_q128WGSL = (i64, inline = true) => {
    if (inline) {
        return wgsl `vec4( ${i64}, 1u, 0u )`;
    }
    else {
        return new WGSLStringModule('whole_i64_to_q128', wgsl `whole_i64_to_q128( ${i64} )`, wgsl `
      fn whole_i64_to_q128( numerator: ${i64WGSL} ) -> ${q128WGSL} {
        return vec4( numerator, 1u, 0u );
      }
    `);
    }
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Returns a LineSegmentIntersection struct containing information about the intersection point(s).
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const intersect_line_segmentsWGSL = (
// vec2i for all points
p0, p1, p2, p3) => {
    return new WGSLStringModule('intersect_line_segments', wgsl `intersect_line_segments( ${p0}, ${p1}, ${p2}, ${p3} )`, wgsl `
    const not_rational = vec4( 0u, 0u, 0u, 0u );
    const not_point = ${IntersectionPointWGSL}( not_rational, not_rational, not_rational, not_rational );
    const not_intersection = ${LineSegmentIntersectionWGSL}( 0u, not_point, not_point );
    
    // TODO: isolate constants
    // NOTE: Should handle zero-length segments fine (will report no intersections, denominator will be 0)
    fn intersect_line_segments( p0: vec2i, p1: vec2i, p2: vec2i, p3: vec2i ) -> ${LineSegmentIntersectionWGSL} {
      let p0x = ${i32_to_i64WGSL(wgsl `p0.x`)};
      let p0y = ${i32_to_i64WGSL(wgsl `p0.y`)};
      let p1x = ${i32_to_i64WGSL(wgsl `p1.x`)};
      let p1y = ${i32_to_i64WGSL(wgsl `p1.y`)};
      let p2x = ${i32_to_i64WGSL(wgsl `p2.x`)};
      let p2y = ${i32_to_i64WGSL(wgsl `p2.y`)};
      let p3x = ${i32_to_i64WGSL(wgsl `p3.x`)};
      let p3y = ${i32_to_i64WGSL(wgsl `p3.y`)};
    
      let d0x = ${subtract_i64_i64WGSL(wgsl `p1x`, wgsl `p0x`)};
      let d0y = ${subtract_i64_i64WGSL(wgsl `p1y`, wgsl `p0y`)};
      let d1x = ${subtract_i64_i64WGSL(wgsl `p3x`, wgsl `p2x`)};
      let d1y = ${subtract_i64_i64WGSL(wgsl `p3y`, wgsl `p2y`)};
    
      let cdx = ${subtract_i64_i64WGSL(wgsl `p2x`, wgsl `p0x`)};
      let cdy = ${subtract_i64_i64WGSL(wgsl `p2y`, wgsl `p0y`)};
    
      let denominator = ${subtract_i64_i64WGSL(mul_i64_i64WGSL(wgsl `d0x`, wgsl `d1y`), mul_i64_i64WGSL(wgsl `d0y`, wgsl `d1x`))};
    
      if ( ${is_zero_u64WGSL(wgsl `denominator`)} ) {
        // such that p0 + t * ( p1 - p0 ) = p2 + ( a * t + b ) * ( p3 - p2 )
        // an equivalency between lines
        var a: q128;
        var b: q128;
    
        let d1x_zero = ${is_zero_u64WGSL(wgsl `d1x`)};
        let d1y_zero = ${is_zero_u64WGSL(wgsl `d1y`)};
    
        // if ( d0s === 0 || d1s === 0 ) {
        //   return NO_OVERLAP;
        // }
        //
        // a = d0s / d1s;
        // b = ( p0s - p2s ) / d1s;
    
        // TODO: can we reduce the branching here?
        // Find a dimension where our line is not degenerate (e.g. covers multiple values in that dimension)
        // Compute line equivalency there
        if ( d1x_zero && d1y_zero ) {
          // DEGENERATE case for second line, it's a point, bail out
          return not_intersection;
        }
        else if ( d1x_zero ) {
          // if d1x is zero AND our denominator is zero, that means d0x or d1y must be zero. We checked d1y above, so d0x must be zero
          if ( p0.x != p2.x ) {
            // vertical lines, BUT not same x, so no intersection
            return not_intersection;
          }
          a = ${i64_to_q128WGSL(wgsl `d0y`, wgsl `d1y`)};
          b = ${i64_to_q128WGSL(negate_i64WGSL(wgsl `cdy`), wgsl `d1y`)};
        }
        else if ( d1y_zero ) {
          // if d1y is zero AND our denominator is zero, that means d0y or d1x must be zero. We checked d1x above, so d0y must be zero
          if ( p0.y != p2.y ) {
            // horizontal lines, BUT not same y, so no intersection
            return not_intersection;
          }
          a = ${i64_to_q128WGSL(wgsl `d0x`, wgsl `d1x`)};
          b = ${i64_to_q128WGSL(negate_i64WGSL(wgsl `cdx`), wgsl `d1x`)};
        }
        else {
          // we have non-axis-aligned second line, use that to compute a,b for each dimension, and we're the same "line"
          // iff those are consistent
          if ( ${is_zero_u64WGSL(wgsl `d0x`)} && ${is_zero_u64WGSL(wgsl `d0y`)} ) {
            // DEGENERATE first line, it's a point, bail out
            return not_intersection;
          }
          let ax = ${i64_to_q128WGSL(wgsl `d0x`, wgsl `d1x`)};
          let ay = ${i64_to_q128WGSL(wgsl `d0y`, wgsl `d1y`)};
          if ( !${equals_cross_mul_q128WGSL(wgsl `ax`, wgsl `ay`)} ) {
            return not_intersection;
          }
          let bx = ${i64_to_q128WGSL(negate_i64WGSL(wgsl `cdx`), wgsl `d1x`)};
          let by = ${i64_to_q128WGSL(negate_i64WGSL(wgsl `cdy`), wgsl `d1y`)};
          if ( !${equals_cross_mul_q128WGSL(wgsl `bx`, wgsl `by`)} ) {
            return not_intersection;
          }
    
          // Pick the one with a non-zero a, so it is invertible
          if ( ${is_zero_q128WGSL(wgsl `ax`)} ) {
            a = ay;
            b = by;
          }
          else {
            a = ax;
            b = bx;
          }
        }
    
        var points: u32 = 0u;
        var results = array<${IntersectionPointWGSL}, 2u>( not_point, not_point );
    
        // p0 + t * ( p1 - p0 ) = p2 + ( a * t + b ) * ( p3 - p2 )
        // i.e. line0( t ) = line1( a * t + b )
        // replacements for endpoints:
        // t=0       =>  t0=0,        t1=b
        // t=1       =>  t0=1,        t1=a+b
        // t=-b/a    =>  t0=-b/a,     t1=0
        // t=(1-b)/a =>  t0=(1-b)/a,  t1=1
    
        // NOTE: cases become identical if b=0, b=1, b=-a, b=1-a, HOWEVER these would not be internal, so they would be
        // excluded, and we can ignore them
    
        // t0=0, t1=b, p0
        let case1t1 = b;
        if ( ${ratio_test_q128WGSL(wgsl `case1t1`)} == 2i ) {
          let p = ${IntersectionPointWGSL}( ${ZERO_q128WGSL}, ${reduce_q128WGSL(wgsl `case1t1`)}, ${whole_i64_to_q128WGSL(wgsl `p0x`)}, ${whole_i64_to_q128WGSL(wgsl `p0y`)} );
          results[ points ] = p;
          points += 1u;
        }
    
        // t0=1, t1=a+b, p1
        let case2t1 = vec4( ${add_i64_i64WGSL(wgsl `a.xy`, wgsl `b.xy`)}, a.zw ); // abuse a,b having same denominator
        if ( ${ratio_test_q128WGSL(wgsl `case2t1`)} == 2i ) {
          let p = ${IntersectionPointWGSL}( ${ONE_q128WGSL}, ${reduce_q128WGSL(wgsl `case2t1`)}, ${whole_i64_to_q128WGSL(wgsl `p1x`)}, ${whole_i64_to_q128WGSL(wgsl `p1y`)} );
          results[ points ] = p;
          points += 1u;
        }
    
        // t0=-b/a, t1=0, p2
        let case3t0 = ${i64_to_q128WGSL(negate_i64WGSL(wgsl `b.xy`), wgsl `a.xy`)}; // abuse a,b having same denominator
        if ( ${ratio_test_q128WGSL(wgsl `case3t0`)} == 2i ) {
          let p = ${IntersectionPointWGSL}( ${reduce_q128WGSL(wgsl `case3t0`)}, ${ZERO_q128WGSL}, ${whole_i64_to_q128WGSL(wgsl `p2x`)}, ${whole_i64_to_q128WGSL(wgsl `p2y`)} );
          results[ points ] = p;
          points += 1u;
        }
    
        // t0=(1-b)/a, t1=1, p3
        // ( 1 - b ) / a = ( denom - b_numer ) / denom / ( a_numer / denom ) = ( denom - b_numer ) / a_numer
        let case4t0 = ${i64_to_q128WGSL(subtract_i64_i64WGSL(wgsl `a.zw`, wgsl `b.xy`), wgsl `a.xy`)};
        if ( ${ratio_test_q128WGSL(wgsl `case4t0`)} == 2i ) {
          let p = ${IntersectionPointWGSL}( ${reduce_q128WGSL(wgsl `case4t0`)}, ${ONE_q128WGSL}, ${whole_i64_to_q128WGSL(wgsl `p3x`)}, ${whole_i64_to_q128WGSL(wgsl `p3y`)} );
          results[ points ] = p;
          points += 1u;
        }
    
        return ${LineSegmentIntersectionWGSL}( points, results[ 0 ], results[ 1 ] );
      }
      else {
        let t_numerator = ${subtract_i64_i64WGSL(mul_i64_i64WGSL(wgsl `cdx`, wgsl `d1y`), mul_i64_i64WGSL(wgsl `cdy`, wgsl `d1x`))};
        let u_numerator = ${subtract_i64_i64WGSL(mul_i64_i64WGSL(wgsl `cdx`, wgsl `d0y`), mul_i64_i64WGSL(wgsl `cdy`, wgsl `d0x`))};
    
        // This will move the sign to the numerator, BUT won't do the reduction (let us first see if there is an intersection)
        let t_raw = ${i64_to_q128WGSL(wgsl `t_numerator`, wgsl `denominator`)};
        let u_raw = ${i64_to_q128WGSL(wgsl `u_numerator`, wgsl `denominator`)};
    
        // 2i means totally internal, 1i means on an endpoint, 0i means totally external
        let t_cmp = ${ratio_test_q128WGSL(wgsl `t_raw`)};
        let u_cmp = ${ratio_test_q128WGSL(wgsl `u_raw`)};
    
        if ( t_cmp <= 0i || u_cmp <= 0i ) {
          return not_intersection; // outside one or both segments
        }
        else if ( t_cmp == 1i && u_cmp == 1i ) {
          return not_intersection; // on endpoints of both segments (we ignore that, we only want something internal to one)
        }
        else {
          // use parametric segment definition to get the intersection point
          // x0 + t * (x1 - x0)
          // p0x + t_numerator / denominator * d0x
          // ( denominator * p0x + t_numerator * d0x ) / denominator
          let x_numerator = ${add_i64_i64WGSL(mul_i64_i64WGSL(wgsl `denominator`, wgsl `p0x`), mul_i64_i64WGSL(wgsl `t_numerator`, wgsl `d0x`))};
          let y_numerator = ${add_i64_i64WGSL(mul_i64_i64WGSL(wgsl `denominator`, wgsl `p0y`), mul_i64_i64WGSL(wgsl `t_numerator`, wgsl `d0y`))};
    
          let x_raw = ${i64_to_q128WGSL(wgsl `x_numerator`, wgsl `denominator`)};
          let y_raw = ${i64_to_q128WGSL(wgsl `y_numerator`, wgsl `denominator`)};
    
          let x = ${reduce_q128WGSL(wgsl `x_raw`)};
          let y = ${reduce_q128WGSL(wgsl `y_raw`)};
    
          let t = ${reduce_q128WGSL(wgsl `t_raw`)};
          let u = ${reduce_q128WGSL(wgsl `u_raw`)};
    
          // NOTE: will t/u be exactly 0,1 for endpoints if they are endpoints, no?
          return ${LineSegmentIntersectionWGSL}( 1u, ${IntersectionPointWGSL}( t, u, x, y ), not_point );
        }
      }
    }
`);
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Converts a u32 to a u64.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const u32_to_u64WGSL = (u32, inline = true) => {
    if (inline) {
        return wgsl `vec2<u32>( ${u32}, 0u )`;
    }
    else {
        return new WGSLStringModule('u32_to_u64', wgsl `u32_to_u64( ${u32} )`, wgsl `
      fn u32_to_u64( x: u32 ) -> ${u64WGSL} {
        return vec2<u32>( x, 0u );
      }
    `);
    }
};

// Copyright 2024-2025, University of Colorado Boulder
/**
 * Executes a RenderProgram in WGSL.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
const evaluate_render_program_instructionsWGSL = (render_program_index, edgesOffset, numEdges, isFullArea, needsFace, area, minX, minY, maxX, maxY, minXCount, minYCount, maxXCount, maxYCount, providedOptions) => {
    const options = optionize()({
        stackSize: 10,
        instructionStackSize: 8
    }, providedOptions);
    const getInstructionWGSL = options.getRenderProgramInstruction;
    return new WGSLStringModule('evaluate_render_program_instructions', wgsl `evaluate_render_program_instructions( ${render_program_index}, ${edgesOffset}, ${numEdges}, ${isFullArea}, ${needsFace}, ${area}, ${minX}, ${minY}, ${maxX}, ${maxY}, ${minXCount}, ${minYCount}, ${maxXCount}, ${maxYCount} )`, wgsl `
    const oops_inifinite_loop_code = vec4f( 5f, 4f, -5f, -4f );
    
    // TODO: how to handle constant RenderPrograms
    
    // Returns success (didn't fail during loop)
    fn compute_centroid(
      centroid: ptr<function, vec2f>,
      edgesOffset: u32,
      numEdges: u32,
      isFullArea: bool,
      area: f32,
      minX: f32,
      minY: f32,
      maxX: f32,
      maxY: f32,
      minXCount: i32,
      minYCount: i32,
      maxXCount: i32,
      maxYCount: i32
    ) -> bool {
      // TODO: more simplification
    
      let bounds_centroid = 0.5f * vec2( minX + maxX, minY + maxY );
    
      if ( isFullArea ) {
        *centroid = bounds_centroid;
      }
      else {
        // TODO: more comments about the math here
        var centroid_partial = 6f * bounds_centroid * vec2(
          ( minX - maxX ) * ( f32( minYCount ) * minY + f32( maxYCount ) * maxY ),
          ( maxY - minY ) * ( f32( minXCount ) * minX + f32( maxXCount ) * maxX )
        );
    
        let endIndex = edgesOffset + numEdges;
        var oops_count = 0u;
        for ( var i = edgesOffset; i < endIndex; i++ ) {
          oops_count++;
          if ( oops_count > 0xfffu ) {
            return false;
          }
    
          let edge = ${options.getLinearEdge(wgsl `i`)};
    
          let p0x = edge.startPoint.x;
          let p0y = edge.startPoint.y;
          let p1x = edge.endPoint.x;
          let p1y = edge.endPoint.y;
    
          let base = p0x * ( 2f * p0y + p1y ) + p1x * ( p0y + 2f * p1y );
          centroid_partial += base * vec2( p0x - p1x, p1y - p0y );
        }
    
        *centroid = centroid_partial / ( 6f * area );
      }
    //  *centroid = bounds_centroid;
    
      return true;
    }
    
    fn evaluate_render_program_instructions(
      render_program_index: u32,
      edgesOffset: u32,
      numEdges: u32,
      isFullArea: bool,
      needsFace: bool,
      area: f32,
      minX: f32,
      minY: f32,
      maxX: f32,
      maxY: f32,
      minXCount: i32,
      minYCount: i32,
      maxXCount: i32,
      maxYCount: i32
    ) -> vec4f {
    //  return vec4f( 0.01f, 0.01f, 0.01f, 0.01f );
      var stack: array<vec4f,${decimalS(options.stackSize)}>;
      var instruction_stack: array<u32,${decimalS(options.instructionStackSize)}>;
    
      var stack_length = 0u;
      var instruction_stack_length = 0u;
    
      var instruction_address = render_program_index;
      var is_done = false;
    
      var oops_count = 0u;
    
      var fake_centroid = 0.5f * vec2f( maxX + minX, maxY + minY );
      var real_centroid = fake_centroid;
      // Conditionally compute the real centroid (compute it FOR NOW if we have the face data)
      if ( needsFace ) {
        let centroid_success = compute_centroid(
          &real_centroid,
          edgesOffset, numEdges, isFullArea, area,
          minX, minY, maxX, maxY,
          minXCount, minYCount, maxXCount, maxYCount
        );
        if ( !centroid_success ) {
          return oops_inifinite_loop_code;
        }
      }
    
      while ( !is_done ) {
        oops_count++;
        if ( oops_count > 0xfffu ) {
          return oops_inifinite_loop_code;
        }
    
        let start_address = instruction_address;
        let instruction_u32 = ${getInstructionWGSL(wgsl `instruction_address`)};
    
        let code = ( instruction_u32 & 0xffu );
    
        var instruction_length: u32;
        // High 4 bits all zero >= 1 length
        if ( ( code >> 4u ) == 0u ) {
          instruction_length = 1u;
        }
        // High 2 bits set >= variable length
        else if ( ( code & 0xc0u ) != 0u ) {
          instruction_length = ( code & 0x1fu ) + 2u * ( instruction_u32 >> 16u );
        }
        // Just high bit set, we'll read the length in the lower-5 bits
        else {
          instruction_length = ( code & 0x1fu );
        }
        instruction_address += instruction_length;
    
        switch ( code ) {
          case ${u32S(RenderInstruction.ExitCode)}: {
            is_done = true;
          }
          case ${u32S(RenderInstruction.ReturnCode)}: {
            instruction_stack_length--;
            instruction_address = instruction_stack[ instruction_stack_length ];
          }
          case ${u32S(RenderInstruction.PushCode)}: {
            stack[ stack_length ] = bitcast<vec4<f32>>( vec4(
              ${getInstructionWGSL(wgsl `start_address + 1u`)},
              ${getInstructionWGSL(wgsl `start_address + 2u`)},
              ${getInstructionWGSL(wgsl `start_address + 3u`)},
              ${getInstructionWGSL(wgsl `start_address + 4u`)}
            ) );
            stack_length++;
          }
          case ${u32S(RenderInstruction.StackBlendCode)}: {
            let background = stack[ stack_length - 1u ];
            let foreground = stack[ stack_length - 2u ];
    
            stack_length--;
    
            // Assume premultiplied
            stack[ stack_length - 1u ] = ( 1f - foreground.a ) * background + foreground;
          }
          case ${u32S(RenderInstruction.LinearBlendCode)}: {
            let zero_color = stack[ stack_length - 1u ];
            let one_color = stack[ stack_length - 2u ];
            let t = stack[ stack_length - 3u ].x;
    
            stack_length -= 2u;
    
            if ( t <= 0f || t >= 1f ) {
              // If we're out of this range, the "top" value will always be this
              stack[ stack_length - 1u ] = zero_color;
            }
            else {
              let minus_t = 1f - t;
    
              stack[ stack_length - 1u ] = zero_color * minus_t + one_color * t;
            }
          }
          case ${u32S(RenderInstruction.OpaqueJumpCode)}: {
            let offset = instruction_u32 >> 8u;
            let color = stack[ stack_length - 1u ];
            if ( color.a >= ${f32S(1 - 1e-5)} ) {
              instruction_address = start_address + offset; // jump to offset
            }
          }
          case ${u32S(RenderInstruction.NormalizeCode)}: {
            stack[ stack_length - 1u ] = normalize( stack[ stack_length - 1u ] );
          }
          case ${u32S(RenderInstruction.PremultiplyCode)}: {
            stack[ stack_length - 1u ] = ${premultiplyWGSL(wgsl `stack[ stack_length - 1u ]`)};
          }
          case ${u32S(RenderInstruction.UnpremultiplyCode)}: {
            stack[ stack_length - 1u ] = ${unpremultiplyWGSL(wgsl `stack[ stack_length - 1u ]`)};
          }
          case ${u32S(RenderInstruction.SRGBToLinearSRGBCode)}: {
            let color = stack[ stack_length - 1u ];
            stack[ stack_length - 1u ] = vec4( ${sRGB_to_linear_sRGBWGSL(wgsl `color.rgb`)}, color.a );
          }
          case ${u32S(RenderInstruction.LinearSRGBToSRGBCode)}: {
            let color = stack[ stack_length - 1u ];
            stack[ stack_length - 1u ] = vec4( ${linear_sRGB_to_sRGBWGSL(wgsl `color.rgb`)}, color.a );
          }
          case ${u32S(RenderInstruction.LinearDisplayP3ToLinearSRGBCode)}: {
            let color = stack[ stack_length - 1u ];
            stack[ stack_length - 1u ] = vec4( ${linear_displayP3_to_linear_sRGBWGSL(wgsl `color.rgb`)}, color.a );
          }
          case ${u32S(RenderInstruction.LinearSRGBToLinearDisplayP3Code)}: {
            let color = stack[ stack_length - 1u ];
            stack[ stack_length - 1u ] = vec4( ${linear_sRGB_to_linear_displayP3WGSL(wgsl `color.rgb`)}, color.a );
          }
          case ${u32S(RenderInstruction.OklabToLinearSRGBCode)}: {
            let color = stack[ stack_length - 1u ];
            stack[ stack_length - 1u ] = vec4( ${oklab_to_linear_sRGBWGSL(wgsl `color.rgb`)}, color.a );
          }
          case ${u32S(RenderInstruction.LinearSRGBToOklabCode)}: {
            let color = stack[ stack_length - 1u ];
            stack[ stack_length - 1u ] = vec4( ${linear_sRGB_to_oklabWGSL(wgsl `color.rgb`)}, color.a );
          }
          case ${u32S(RenderInstruction.NormalDebugCode)}: {
            let normal = stack[ stack_length - 1u ];
            stack[ stack_length - 1u ] = vec4( normal.rgb * 0.5f + 0.5f, 1f );
          }
          case ${u32S(RenderInstruction.BlendComposeCode)}: {
            let color_a = stack[ stack_length - 1u ];
            let color_b = stack[ stack_length - 2u ];
            let compose_type = ( instruction_u32 >> 8u ) & 0x7u;
            let blend_type = ( instruction_u32 >> 11u ) & 0xfu;
    
            stack_length--;
    
            stack[ stack_length - 1u ] = ${blend_composeWGSL(wgsl `color_a`, wgsl `color_b`, wgsl `compose_type`, wgsl `blend_type`)};
          }
          case ${u32S(RenderInstruction.MultiplyScalarCode)}: {
            let factor = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 1u`)} );
            stack[ stack_length - 1u ] = factor * stack[ stack_length - 1u ];
          }
          case ${u32S(RenderInstruction.ComputeLinearBlendRatioCode)}, ${u32S(RenderInstruction.ComputeRadialBlendRatioCode)}: {
            var t: f32;
    
            let accuracy = instruction_u32 >> 8u;
            let zero_offset = ${getInstructionWGSL(wgsl `start_address + 1u`)};
            let one_offset = ${getInstructionWGSL(wgsl `start_address + 2u`)};
            let blend_offset = ${getInstructionWGSL(wgsl `start_address + 3u`)};
            if ( code == ${u32S(RenderInstruction.ComputeLinearBlendRatioCode)} ) {
              let scaled_normal = bitcast<vec2<f32>>( vec2(
                ${getInstructionWGSL(wgsl `start_address + 4u`)},
                ${getInstructionWGSL(wgsl `start_address + 5u`)}
              ) );
              let offset = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 6u`)} );
    
              let centroid = select( fake_centroid, real_centroid, accuracy == 0u );
              let dot_product = dot( scaled_normal, centroid );
              t = dot_product - offset;
            }
            else {
              let inverse_transform = mat3x3(
                bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 4u`)} ),
                bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 7u`)} ),
                0f,
                bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 5u`)} ),
                bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 8u`)} ),
                0f,
                bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 6u`)} ),
                bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 9u`)} ),
                1f
              );
              let radius0 = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 10u`)} );
              let radius1 = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 11u`)} );
    
              var average_distance: f32;
    
              if ( accuracy == 0u ) {
                // TODO: evaluate the integral!!!!!
                let localPoint = inverse_transform * vec3( real_centroid, 1f );
                average_distance = length( localPoint.xy );
              }
              else {
                let centroid = select( fake_centroid, real_centroid, accuracy == 1u );
                let localPoint = inverse_transform * vec3( centroid, 1f );
                average_distance = length( localPoint.xy );
              }
    
              t = ( average_distance - radius0 ) / ( radius1 - radius0 );
            }
    
            stack[ stack_length ] = vec4( t, 0f, 0f, 0f );
            stack_length++;
    
            // Queue these up to be in "reverse" order
            instruction_address = start_address + blend_offset; // jump to blend_location
    
            let has_zero = t < 1f;
            let has_one = t > 0f;
    
            if ( !has_zero || !has_one ) {
              stack_length++;
            }
    
            if ( has_zero ) {
              // call zero_location
              instruction_stack[ instruction_stack_length ] = instruction_address;
              instruction_stack_length++;
              instruction_address = start_address + zero_offset;
            }
    
            if ( has_one ) {
              // call one_location
              instruction_stack[ instruction_stack_length ] = instruction_address;
              instruction_stack_length++;
              instruction_address = start_address + one_offset;
            }
          }
          case ${u32S(RenderInstruction.ComputeLinearGradientRatioCode)}, ${u32S(RenderInstruction.ComputeRadialGradientRatioCode)}: {
            let is_linear = code == ${u32S(RenderInstruction.ComputeLinearGradientRatioCode)};
    
            let accuracy = ( instruction_u32 >> 8u ) & 0x7u;
            let extend = ( instruction_u32 >> 11u ) & 0x2u;
            let ratio_count = instruction_u32 >> 16u;
    
            let transform = mat3x3(
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 1u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 4u`)} ),
              0f,
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 2u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 5u`)} ),
              0f,
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 3u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 6u`)} ),
              1f
            );
    
            var t: f32;
            if ( is_linear ) {
              let inverse_transform = transform;
              let start = bitcast<vec2<f32>>( vec2(
                  ${getInstructionWGSL(wgsl `start_address + 7u`)},
                  ${getInstructionWGSL(wgsl `start_address + 8u`)}
              ) );
              let grad_delta = bitcast<vec2<f32>>( vec2(
                  ${getInstructionWGSL(wgsl `start_address + 9u`)},
                  ${getInstructionWGSL(wgsl `start_address + 10u`)}
              ) );
    
              let centroid = select( fake_centroid, real_centroid, accuracy == 0u || accuracy == 2u );
    
              let local_point = ( inverse_transform * vec3( centroid, 1f ) ).xy;
              let local_delta = local_point - start;
    
              let raw_t = select( 0f, dot( local_delta, grad_delta ) / dot( grad_delta, grad_delta ), length( grad_delta ) > 0f, );
    
              t = ${extend_f32WGSL(wgsl `raw_t`, wgsl `extend`)};
            }
            else {
              let kind = ( instruction_u32 >> 13u ) & 0x3u;
              let is_swapped = ( ( instruction_u32 >> 15u ) % 0x1u ) != 0u;
              let conic_transform = transform;
              let focal_x = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 7u`)} );
              let radius = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 8u`)} );

              let is_strip = kind == ${u32S(RadialGradientType.Strip)};
              let is_circular = kind == ${u32S(RadialGradientType.Circular)};
              let is_focal_on_circle = kind == ${u32S(RadialGradientType.FocalOnCircle)};
              let r1_recip = select( 1.f / radius, 0f, is_circular );
              let less_scale = select( 1f, -1f, is_swapped || ( 1f - focal_x ) < 0f );
              let t_sign = sign( 1f - focal_x );
    
              // TODO: centroid handling for this
              let centroid = select( fake_centroid, real_centroid, accuracy == 0u || accuracy == 1u || accuracy == 3u );
              let point = centroid;
    
              // Pixel-specifics
              // TODO: optimization?
              let local_xy = ( conic_transform * vec3( point, 1f ) ).xy;
              let x = local_xy.x;
              let y = local_xy.y;
              let xx = x * x;
              let yy = y * y;
              var is_valid = true;
              if ( is_strip ) {
                let a = radius - yy;
                t = sqrt( a ) + x;
                is_valid = a >= 0f;
              }
              else if ( is_focal_on_circle ) {
                t = ( xx + yy ) / x;
                is_valid = t >= 0f && x != 0f;
              }
              else if ( radius > 1f ) {
                t = sqrt( xx + yy ) - x * r1_recip;
              }
              else { // radius < 1
                let a = xx - yy;
                t = less_scale * sqrt( a ) - x * r1_recip;
                is_valid = a >= 0f && t >= 0f;
              }
              if ( is_valid ) {
                t = ${extend_f32WGSL(wgsl `focal_x + t_sign * t`, wgsl `extend`)};
                if ( is_swapped ) {
                  t = 1f - t;
                }
              }
            }
    
            let blend_offset = select( 9u, 11u, is_linear );
            let stops_offset = blend_offset + 1u; // ratio, stopOffset pairs
    
            let blend_address = start_address + ${getInstructionWGSL(wgsl `start_address + blend_offset`)};
    
            var i = -1i;
            while (
              i < i32( ratio_count ) - 1i &&
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + stops_offset + 2u * u32( i + 1i )`)} ) < t
            ) {
              oops_count++;
              if ( oops_count > 0xfffu ) {
                return oops_inifinite_loop_code;
              }
    
              i++;
            }
    
            // Queue these up to be in "reverse" order
            instruction_address = blend_address; // jump to blend_location
    
            if ( i == -1i ) {
              stack[ stack_length ] = vec4( 0f, 0f, 0f, 0f ); // number 0, for t
              stack[ stack_length + 1u ] = vec4( 0f, 0f, 0f, 0f ); // spacer
              stack_length += 2;
    
              // call stopLocations[ 0 ]
              instruction_stack[ instruction_stack_length ] = instruction_address;
              instruction_stack_length++;
              instruction_address = start_address + ${getInstructionWGSL(wgsl `start_address + stops_offset + 1u`)};
            }
            else if ( i == i32( ratio_count ) - 1i ) {
              stack[ stack_length ] = vec4( 1f, 0f, 0f, 0f ); // number 1, for t
              stack[ stack_length + 1u ] = vec4( 0f, 0f, 0f, 0f ); // spacer
              stack_length += 2;
    
              // call stopLocations[ i ]
              instruction_stack[ instruction_stack_length ] = instruction_address;
              instruction_stack_length++;
              instruction_address = start_address + ${getInstructionWGSL(wgsl `start_address + stops_offset + 2u * u32( i ) + 1u`)};
            }
            else {
              // TODO: create stops_address to factor out these additions!
              let ratio_before = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + stops_offset + 2u * u32( i )`)} );
              let ratio_after = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + stops_offset + 2u * u32( i + 1i )`)} );
    
              let ratio = ( t - ratio_before ) / ( ratio_after - ratio_before );
    
              stack[ stack_length ] = vec4( ratio, 0f, 0f, 0f );
              stack_length++;
    
              let hasBefore = ratio < 1f;
              let hasAfter = ratio > 0f;
    
              if ( !hasBefore || !hasAfter ) {
                stack[ stack_length ] = vec4( 0f, 0f, 0f, 0f ); // spacer TODO: can we NOT write to our spacers?
                stack_length++;
              }
    
              if ( hasBefore ) {
                // call stopLocations[ i ]
                instruction_stack[ instruction_stack_length ] = instruction_address;
                instruction_stack_length++;
                instruction_address = start_address + ${getInstructionWGSL(wgsl `start_address + stops_offset + 2u * u32( i ) + 1u`)};
              }
    
              if ( hasAfter ) {
                // call stopLocations[ i + 1 ]
                instruction_stack[ instruction_stack_length ] = instruction_address;
                instruction_stack_length++;
                instruction_address = start_address + ${getInstructionWGSL(wgsl `start_address + stops_offset + 2u * u32( i + 1i ) + 1u`)};
              }
            }
          }
          case ${u32S(RenderInstruction.BarycentricBlendCode)}, ${u32S(RenderInstruction.BarycentricPerspectiveBlendCode)}: {
            let accuracy = instruction_u32 >> 8u;
    
            let det = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 1u`)} );
            let diff_a = bitcast<vec2<f32>>( vec2(
              ${getInstructionWGSL(wgsl `start_address + 2u`)},
              ${getInstructionWGSL(wgsl `start_address + 3u`)}
            ) );
            let diff_b = bitcast<vec2<f32>>( vec2(
              ${getInstructionWGSL(wgsl `start_address + 4u`)},
              ${getInstructionWGSL(wgsl `start_address + 5u`)}
            ) );
            let point_c = bitcast<vec2<f32>>( vec2(
              ${getInstructionWGSL(wgsl `start_address + 6u`)},
              ${getInstructionWGSL(wgsl `start_address + 7u`)}
            ) );
    
            let color_a = stack[ stack_length - 1u ];
            let color_b = stack[ stack_length - 2u ];
            let color_c = stack[ stack_length - 3u ];
    
            stack_length -= 2u;
    
            let point = select( fake_centroid, real_centroid, accuracy == 0u );
    
            let lambda_a = dot( diff_a, point - point_c ) / det;
            let lambda_b = dot( diff_b, point - point_c ) / det;
            let lambda_c = 1f - lambda_a - lambda_b;
    
            if ( code == ${u32S(RenderInstruction.BarycentricBlendCode)} ) {
              stack[ stack_length - 1u ] = color_a * lambda_a + color_b * lambda_b + color_c * lambda_c;
            }
            // Perspective-correction
            else {
              let z_inverse_a = lambda_a * bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 8u`)} );
              let z_inverse_b = lambda_b * bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 9u`)} );
              let z_inverse_c = lambda_c * bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 10u`)} );
    
              stack[ stack_length - 1u ] = (
                color_a * z_inverse_a +
                color_b * z_inverse_b +
                color_c * z_inverse_c
              ) / ( z_inverse_a + z_inverse_b + z_inverse_c );
            }
          }
          case ${u32S(RenderInstruction.FilterCode)}: {
            // TODO: don't require a transpose here, just do it
            let matrix = transpose( mat4x4(
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 1u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 2u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 3u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 4u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 5u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 6u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 7u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 8u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 9u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 10u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 11u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 12u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 13u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 14u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 15u`)} ),
              bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 16u`)} )
            ) );
    
            let translation = bitcast<vec4<f32>>( vec4(
              ${getInstructionWGSL(wgsl `start_address + 17u`)},
              ${getInstructionWGSL(wgsl `start_address + 18u`)},
              ${getInstructionWGSL(wgsl `start_address + 19u`)},
              ${getInstructionWGSL(wgsl `start_address + 20u`)}
            ) );
    
            stack[ stack_length - 1u ] = matrix * stack[ stack_length - 1u ] + translation;
          }
          // TODO: ImageCode
          case ${u32S(RenderInstruction.PhongCode)}: {
            let alpha = bitcast<f32>( ${getInstructionWGSL(wgsl `start_address + 1u`)} );
            let num_lights = ${getInstructionWGSL(wgsl `start_address + 2u`)};
    
            let ambient = stack[ stack_length - 1u ];
            let diffuse = stack[ stack_length - 2u ];
            let specular = stack[ stack_length - 3u ];
            let position = stack[ stack_length - 4u ];
            let normal = stack[ stack_length - 5u ];
            stack_length -= 4u;
    
            var output = ambient;
    
            // TODO: don't assume camera is at origin?
            let view_direction = normalize( -position );
    
            for ( var i = 0u; i < num_lights; i++ ) {
              oops_count++;
              if ( oops_count > 0xfffu ) {
                return oops_inifinite_loop_code;
              }
    
              // TODO: really examine stack sizes, since it affects what we do here!!!
    
              let light_direction = stack[ stack_length - 2u ];
              let light_color = stack[ stack_length - 3u ];
              stack_length -= 2u;
    
              let dot_product = dot( normal, light_direction );
              if ( dot_product > 0f ) {
                // TODO: consider reflect()? TODO: make sure this isn't reversed (we have different sign convention, no?)
                // TODO: I just had to add an abs() below because the sign was wrong
                let reflection = 2f * dot_product * normal - light_direction;
                let specular_amount = pow( abs( dot( reflection, view_direction ) ), alpha );
    
                output += light_color * (
                  // keep alphas?
                  diffuse * vec4( vec3( dot_product ), 1f ) +
                  specular * vec4( vec3( specular_amount ), 1f )
                );
              }
            }
    
            // clamp for now
            stack[ stack_length - 1u ] = clamp( output, vec4( 0f ), vec4( 1f ) );
          }
          default: {
            // TODO: a more noticeable error code?
            return vec4f( -1f, -1f, -1f, -1f );
          }
        }
      }
    
      // TODO: error handling?
    
      return stack[ 0u ];
    }
`);
};

