            const now = phetAudioContext.currentTime;
            this.duckingGainNode?.gain.cancelScheduledValues(now);
            this.duckingGainNode?.gain.setTargetAtTime(duckOutput ? AUDIO_DUCKING_LEVEL : 1, now, timeConstant);
