/**
 * Display a score as 'N *', where N is a number and '*' is a star.
 * If N is 0, it is hidden and the star is grayed out.
 * See specification in https://github.com/phetsims/vegas/issues/59.
 *
 * @author Andrea Lin
 */
class ScoreDisplayNumberAndStar extends HBox {
    constructor(scoreProperty, providedOptions) {
        const options = optionize()({
            // SelfOptions
            font: StatusBar.DEFAULT_FONT,
            textFill: 'black',
            scoreDecimalPlaces: 0,
            starNodeOptions: {
                starShapeOptions: {
                    outerRadius: 10,
                    innerRadius: 5
                },
                filledLineWidth: 1.5,
                emptyLineWidth: 1.5
            },
            // HBoxOptions
            spacing: 5
        }, providedOptions);
        super(options);
        // Update number displayed based on score.
        const scorePropertyListener = (score) => {
            const children = [];
            if (score === 0) {
                children.push(new StarNode(combineOptions({ value: 0 }, options.starNodeOptions)));
            }
            else {
                children.push(new Text(toFixed(score, options.scoreDecimalPlaces), {
                    font: options.font,
                    fill: options.textFill
                }));
                children.push(new StarNode(combineOptions({ value: 1 }, options.starNodeOptions)));
            }
            this.children = children;
        };
        scoreProperty.link(scorePropertyListener);
        this.disposeScoreDisplayNumberAndStar = function () {
            scoreProperty.unlink(scorePropertyListener);
        };
    }
    dispose() {
        this.disposeScoreDisplayNumberAndStar();
        super.dispose();
    }
}
vegas.register('ScoreDisplayNumberAndStar', ScoreDisplayNumberAndStar);

